BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-14732'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='8Z6564' OR source_url ~ '[?&]id=14732(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='a9106564-0857-45f2-9f46-782065914732' OR slug='sam-the-kib-koh-kho-khao-resort-8z6564' OR (abs(latitude-8.892045)<0.0001 AND abs(longitude-98.264098)<0.0001 AND abs(land_area_sqm-24000)<1)) THEN RAISE NOTICE 'SAM 8Z6564 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, custom_project_name, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('a9106564-0857-45f2-9f46-782065914732', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'hotel_resort', 'business', 'sale', 'whole_property', 'The Kib เกาะคอเขา รีสอร์ทบนที่ดิน 15 ไร่ ตะกั่วป่า พังงา', 'รายละเอียดทรัพย์

ทรัพย์โรงแรม/รีสอร์ท The Kib เกาะคอเขา บีช รีสอร์ทแอนด์สปา ตำบลเกาะคอเขา อำเภอตะกั่วป่า จังหวัดพังงา บนถนนสายบ้านปากเกาะ–บ้านนอกนา เข้าซอยโรงเรียน โฉนดเลขที่ 15111 จำนวน 1 ฉบับ เนื้อที่ 15 ไร่ หรือ 6,000 ตร.ว. (24,000 ตร.ม.) ราคาประกาศขายทั้งทรัพย์ 98,222,000 บาท รหัส SAM 8Z6564

แปลงสี่เหลี่ยมผืนผ้า ด้านตะวันออกติดถนนกว้างประมาณ 84 เมตร ลึกประมาณ 290 เมตร ผังต้นทางแสดงด้านตะวันตกติดทะเลอันดามัน ภาพชายหาดใช้แสดงบริเวณโดยรอบ ไม่ใช่การรับรองกรรมสิทธิ์ชายหาดหรือขอบเขตที่โอน ถนนหน้าทรัพย์คือซอยโรงเรียน SAM ระบุเป็นทางสาธารณประโยชน์ ผิวลาดยางประมาณ 6 เมตร เขตทางประมาณ 8 เมตร

ห้องพักตามข้อมูลสำรวจ

วิลลาชั้นเดียว Single Private Villa Pool Access 17 หลัง, Single Private Villa Pool GV 10 หลัง และ Beach Front Villa 4 หลัง รวมวิลลา 31 หลัง แยกจากอาคารห้องพัก 2 ชั้น 5 หลัง รวม 20 ห้อง แบบ Superior ชั้นบนและ Deluxe ชั้นล่าง และอาคาร 3 ชั้น 1 หลัง รวม 24 ห้อง แบบ Grand Deluxe ไม่ใช้จำนวนหลังแทนจำนวนห้องนอน และไม่รับรองว่าพร้อมเปิดให้บริการ

ข้อมูลสำรวจยังระบุอาคารต้อนรับและสำนักงาน ภัตตาคาร สปา อาคารจัดเลี้ยงสัมมนามีชั้นใต้ดิน บีชบาร์ อาคารช่างและสำนักงาน 2 ชั้น อาคารเก็บของและห้องเครื่อง และสระว่ายน้ำ 2 สระ

รายการตามทะเบียนและขอบเขตการโอน

ทะเบียนรับโอนของ SAM มี 15 รายการ ซึ่งแต่ละรายการอาจรวมหลายหลัง ได้แก่ บังกะโลชั้นเดียว A จำนวน 14 หลัง พื้นที่ตามรายการประมาณ 59.5 ตร.ม., B จำนวน 13 หลัง ประมาณ 62.9 ตร.ม., C จำนวน 2 หลัง ประมาณ 144 ตร.ม.; บังกะโล 2 ชั้น D จำนวน 4 หลัง ประมาณ 217.35 ตร.ม. และอีก 1 หลัง ประมาณ 253.48 ตร.ม.; อาคารอเนกประสงค์ 2 ชั้น E 1 หลัง ประมาณ 133 ตร.ม.; อาคารห้องช่างและห้องเครื่อง F 90 ตร.ม.; ภัตตาคาร G 572 ตร.ม.; สปา H 112 ตร.ม.; บีชบาร์ I 48 ตร.ม.; โรงแรม 3 ชั้น K 1,852 ตร.ม.; อาคารต้อนรับ J 439 ตร.ม.; อาคารสัมมนา 2 ชั้น L 908 ตร.ม.; และสระว่ายน้ำ 92 กับ 1,298 ตร.ม. ตามต้นทาง ไม่รวมตัวเลขเหล่านี้เป็นพื้นที่ใช้สอยรวม เนื่องจากรายการและวิธีนับต่างกัน

ลักษณะและจำนวนสิ่งปลูกสร้างตามสำรวจต่างจากทะเบียน SAM ระบุว่าการโอนให้ผู้ซื้อทำได้เฉพาะรายการที่จดทะเบียนรับโอนกรรมสิทธิ์เท่านั้น ต้องเทียบทะเบียน ผังขยาย อาคารจริงและรายการที่จะโอน ไม่ถือว่าทุกสิ่งในภาพหรือรายการสำรวจรวมอยู่ในการโอนโดยอัตโนมัติ

ข้อกำหนดและสภาพกิจการ

SAM ระบุว่าทรัพย์อยู่ในพื้นที่กำหนดบริเวณห้ามก่อสร้างตามข้อกำหนด พ.ศ.2544 และ 2551 ออกตามพระราชบัญญัติควบคุมอาคาร พ.ศ.2522 และเกี่ยวข้องกับหลักเกณฑ์จัดทำรายงานผลกระทบสิ่งแวดล้อมเบื้องต้น พ.ศ.2550 ตามประกาศกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม สีผังเมืองตามหัวข้อ SAM เป็นสีเขียวมีกรอบและเส้นทแยงสีขาว ข้อมูลเหล่านี้เป็นข้อระบุของต้นทาง ต้องตรวจข้อกำหนดปัจจุบัน แนวเขตชายฝั่ง ระยะร่น ใบอนุญาตอาคาร/โรงแรมและข้อกำหนดสิ่งแวดล้อมก่อนวางแผนใช้ประโยชน์

ภาพรวมบรรยากาศหนึ่งภาพมีคำกำกับว่าเป็นช่วงก่อนหยุดดำเนินกิจการ จึงติดป้ายเป็นภาพในอดีต ต้นทางไม่ยืนยันสถานะเปิดดำเนินงานล่าสุด รายได้ ผู้เช่า หรือความพร้อมระบบอาคาร สระและห้องพัก ควรตรวจสภาพจริง ไม่เสนอเป็นกิจการพร้อมเปิด

การเดินทางและภาพต้นทาง

จากถนนเพชรเกษม ทล.4 ตะกั่วป่ามุ่งหน้าโคกกลอย ผ่านตลาดบางม่วงและวัดบางม่วง เข้าถนนบ้านน้ำเค็มประมาณ 3.5 กม. ถึงท่าเรือบ้านน้ำเค็ม นั่งเรือไปท่าเรือเกาะคอเขา แล้วใช้ถนนปากเกาะ–บ้านนอกนา ผ่านอาคารหลบภัยสึนามิและวัดกันตาดาราม เข้าซอยโรงเรียนบุญสูงอุปถัมภ์ประมาณ 600 เมตร ทรัพย์อยู่ซ้ายมือ การเข้าถึงตามเส้นทางนี้มีช่วงเดินทางโดยเรือ ควรตรวจบริการและเงื่อนไขการเดินทางปัจจุบัน

ใช้ภาพจริงและผังจาก SAM 22 ภาพ รวมผังขยายสิ่งปลูกสร้างจากเอกสารแนบ ภาพชายหาดมีวันที่ 1 เมษายน 2565 ส่วนภาพอื่นเป็นภาพต้นทางต่างช่วงเวลาและไม่ยืนยันวันถ่ายทั้งหมด ควรนัดดูสภาพปัจจุบัน

พิกัด 8.892045, 98.264098 ดึงจากลิงก์นำทาง SAM และตรงกับแผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด ตรวจราคาและสถานะซื้อตรงวันที่ 15 กันยายน 2569 ติดต่อ SAM โทร.02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 8Z6564 เพื่อยืนยันราคา เอกสาร รายการโอนและเงื่อนไขล่าสุด', 98222000, false, 24000, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'The Kib เกาะคอเขา บีช รีสอร์ทแอนด์สปา', 'ซอยโรงเรียน ถนนบ้านปากเกาะ–บ้านนอกนา', 'เกาะคอเขา', 'ถนนบ้านปากเกาะ–บ้านนอกนา', 8.892045, 98.264098, 'พังงา', 'ตะกั่วป่า', 'เกาะคอเขา', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-the-kib-koh-kho-khao-resort-8z6564') RETURNING id INTO property_listing_id;
