INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=14732&keyref=', '8Z6564', now(), 'Checked2026-09-15. THB98222000,24000sqm,Chanote15111. Survey31villas plus20Superior/Deluxe rooms and24GrandDeluxe rooms; no inferred bedroom total.15registered inventory entries include multiple buildings; registered transfer only. Source building restrictions2001/2008 and environmental criteria2007 require current verification. Historical pre-closure montage labelled; current operations unconfirmed.22source images/plans including expanded attachment; beach photos2022-04-01. Navigation/map agree. No all-status source/code/page/project/deed/nearby duplicate matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'The Kib Koh Kho Khao Resort Property, 15 Rai, Phang Nga', 'The Kib Koh Kho Khao Beach Resort and Spa property, Koh Kho Khao, Takua Pa, Phang Nga, via Ban Pak Ko–Ban Nok Na Road and Soi Rong Rian. One Chanote15111,15rai/6000sq.wah/24000sq.m. SAM whole-property asking price THB98,222,000,reference8Z6564. Approximately rectangular,84m eastern road frontage and290m depth. Source plan shows Andaman Sea to the west; beach context does not establish private beach ownership or transfer boundaries. SAM describes public Soi Rong Rian,6m paved carriageway and8m right of way.

Survey lists31single-storey villas:17Single Private Villa Pool Access,10Single Private Villa Pool GV and4Beach Front Villa. Separately,five2-storey buildings contain20Superior/Deluxe rooms and one3-storey building contains24Grand Deluxe rooms. Building counts are not bedroom counts or confirmation of operational readiness. Other surveyed facilities include reception/office,restaurant,spa,banquet/seminar building with basement,beach bar,2-storey technical/office building,storage/plant rooms and2pools.

Registered acquisition has15inventory entries,not15buildings. Bungalows A:14at source-listed area59.5sq.m.; B:13at62.9; C:2at144; two-storey D:4at217.35 plus1at253.48. Two-storey multipurpose E:1at133; technical/plant F:90; restaurant G:572; spa H:112; beach bar I:48; three-storey hotel K:1852; reception J:439; two-storey seminar L:908; pools92and1298sq.m. These source-listed areas are not summed into total usable area. Surveyed structures differ from registered inventory. SAM expressly limits transfer to registered acquisition items. Reconcile deeds,expanded plan,actual buildings and transfer schedule; not everything pictured/surveyed is automatically transferable.

SAM cites building-prohibition-area provisions from2001and2008 under the1979Building Control Act and2007initial environmental impact reporting criteria. Source zoning colour:green with white border/diagonal lines. Verify current building/coastal/setback/environmental requirements and hotel permits; source references do not establish development permission.

One historical montage is expressly captioned as before cessation of operations. Current reopening/operations,income,occupancy and readiness of rooms,pools and systems are not confirmed. This is not marketed as a ready-to-operate business.

Source access route:Highway4 via Bang Muang to Ban Nam Khem pier,boat to Koh Kho Khao pier,then Pak Ko–Ban Nok Na Road past tsunami shelter and Wat Kantadaram,turn into Bun Sung Uppatham School soi for around600m,property left. This route includes boat travel; verify current services.

